class Ahrara < Formula
  desc "Disposable email with a local inbox for AI agents, QA and automation"
  homepage "https://ahrara.dev"
  license "MIT"

  # BEGIN RELEASE METADATA (generated by scripts/release-manifest.py)
  version "0.2.0"

  on_macos do
    on_arm do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.2.0/ahrara-darwin-aarch64", using: :nounzip
      sha256 "e8721f421817bc327a9db479cc0849208a0a36fcc91945390f936752c032df52"
    end
    on_intel do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.2.0/ahrara-darwin-x86_64", using: :nounzip
      sha256 "419610c384d1c2e811f4c1d413d0c73d32c463224e93b02fe2b73d4582e7aca5"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.2.0/ahrara-linux-aarch64", using: :nounzip
      sha256 "c68db978f5bad31ca28bbe12171e0bd5c7eb6223bda51d9e924d6bdf977c0e7f"
    end
    on_intel do
      url "https://github.com/Hitmasu/Ahrara/releases/download/v0.2.0/ahrara-linux-x86_64", using: :nounzip
      sha256 "82ab0e9e4481923fc3520a096bdf7d0abf3c7c41bf23246a149be973b52dd5f9"
    end
  end
  # END RELEASE METADATA

  def install
    libexec.install File.basename(stable.url) => "ahrara"
    chmod 0755, libexec/"ahrara"
    (libexec/"ahrara.install.json").write <<~JSON
      {"schema_version":1,"method":"brew"}
    JSON
    bin.install_symlink libexec/"ahrara"
  end

  test do
    assert_match "ahrara #{version}", shell_output("#{bin}/ahrara --version")
    output = shell_output("#{bin}/ahrara --config #{testpath}/unused/config.toml --json update")
    result = JSON.parse(output)
    assert_equal "brew", result.fetch("install_method")
    assert_equal false, result.fetch("updated")
    assert_match "brew upgrade ahrara", result.fetch("message")
    refute_path_exists testpath/"unused"
  end
end
